mapper.select:
SELECT usage.id AS usage_id, usage.ai_model_id, COALESCE(model.model_name, '未知模型') AS model_name, COALESCE(detail.vendor_snapshot, model.vendor, 'unknown') AS vendor, COALESCE(detail.is_stream, FALSE) AS is_stream, usage.billing_status, COALESCE(usage.prompt_tokens, 0) AS prompt_tokens, COALESCE(usage.cached_prompt_tokens, 0) AS cached_prompt_tokens, COALESCE(usage.completion_tokens, 0) AS completion_tokens, usage.charged_quota_minor, COALESCE(detail.reserved_quota_minor, 0) AS reserved_quota_minor, usage.finish_reason, usage.failure_code, usage.created_at, usage.settled_at FROM ai_model_api_usage usage LEFT JOIN ai_model_api_usage_detail detail ON detail.usage_id = usage.id LEFT JOIN ai_model model ON model.id = usage.ai_model_id WHERE usage.key_digest = #{keyDigest,jdbcType=BINARY} AND usage.created_at >= #{from,jdbcType=TIMESTAMP_WITH_TIMEZONE} AND usage.created_at < #{to,jdbcType=TIMESTAMP_WITH_TIMEZONE}
AND (usage.created_at, usage.id) < ( #{cursorCreatedAt,jdbcType=TIMESTAMP_WITH_TIMEZONE}, #{cursorId,jdbcType=BINARY} )
ORDER BY usage.created_at DESC, usage.id DESC LIMIT #{limit,jdbcType=INTEGER}
